import java.util.*;

public class Main {
    // A record: fields, constructor, accessors, equals, hashCode, toString are generated
    record Point(int x, int y) {}

    // Shallow immutability trap: a mutable component can still change
    record Bag(List<String> items) {
        Bag { items = List.copyOf(items); } // defensive copy fixes the trap
    }
    record LeakyBag(List<String> items) {}

    public static void main(String[] args) {
        Point p = new Point(1, 2);
        System.out.println(p + " x()=" + p.x());              // accessor is x(), not getX()
        System.out.println("equal by value: " + p.equals(new Point(1, 2)));
        System.out.println("same hash: " + (p.hashCode() == new Point(1, 2).hashCode()));

        List<String> src = new ArrayList<>(List.of("a"));
        LeakyBag leaky = new LeakyBag(src);
        Bag safe = new Bag(src);
        src.add("b");                                          // mutate the original list
        System.out.println("leaky: " + leaky);                // sees the change
        System.out.println("safe:  " + safe);                 // copy was taken, unchanged
        System.out.println("is final: " + java.lang.reflect.Modifier.isFinal(Point.class.getModifiers()));
        System.out.println("extends Record: " + (Point.class.getSuperclass() == Record.class));
    }
}

public class Main {
    record Range(int lo, int hi) {
        // Compact constructor: no parameter list; fields are assigned after this body runs
        Range {
            if (lo > hi) throw new IllegalArgumentException("lo > hi: " + lo + " > " + hi);
        }
        // Non-canonical constructor must delegate to the canonical one
        Range(int single) { this(single, single); }
    }

    record Name(String value) {
        Name {
            value = value.strip();   // reassigning the parameter normalizes the value
        }
    }

    public static void main(String[] args) {
        System.out.println(new Range(1, 5));
        System.out.println(new Range(7));                    // delegates to this(7, 7)
        System.out.println("[" + new Name("  Ada  ").value() + "]");
        try {
            new Range(9, 3);                                  // validation runs for every instance
        } catch (IllegalArgumentException e) {
            System.out.println("rejected: " + e.getMessage());
        }
    }
}

public class Main {
    // Closed hierarchy: only these three kinds exist
    sealed interface Shape permits Circle, Square, Rect {}
    record Circle(double r) implements Shape {}
    record Square(double side) implements Shape {}
    record Rect(double w, double h) implements Shape {}

    // No default needed: the compiler checks every permitted type is covered
    static double area(Shape s) {
        return switch (s) {
            case Circle c -> Math.round(Math.PI * c.r() * c.r() * 100) / 100.0;
            case Square q -> q.side() * q.side();
            case Rect r -> r.w() * r.h();
        };
    }

    public static void main(String[] args) {
        Shape[] shapes = { new Circle(1), new Square(3), new Rect(2, 5) };
        for (Shape s : shapes) {
            System.out.println(s + " area=" + area(s));
        }
        System.out.println("sealed: " + Shape.class.isSealed());
        for (Class<?> c : Shape.class.getPermittedSubclasses()) {
            System.out.println("permits " + c.getSimpleName());
        }
    }
}

public class Main {
    record Point(int x, int y) {}

    static String describe(Object o) {
        return switch (o) {
            case null -> "null value";                                   // explicit null case
            case Integer i when i > 100 -> "big int " + i;              // guard with 'when'
            case Integer i -> "int " + i;
            case String s -> "string of length " + s.length();
            case Point(int x, int y) when x == y -> "diagonal point " + x;  // record pattern
            case Point(var x, var y) -> "point " + x + "," + y;
            default -> "other " + o;
        };
    }

    public static void main(String[] args) {
        Object[] inputs = { 5, 500, "hello", new Point(2, 2), new Point(1, 3), 3.5, null };
        for (Object o : inputs) {
            System.out.println(o + " -> " + describe(o));   // first matching case wins, top to bottom
        }
        try {
            Object n = null;
            switch (n) {                                      // no 'case null' -> NullPointerException
                case String s -> System.out.println(s);
                default -> System.out.println("default");
            }
        } catch (NullPointerException e) {
            System.out.println("NPE without case null");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        // Closing delimiter on its own line: string ends with a newline.
        // Incidental indentation (the minimum) is stripped.
        String a = """
            line one
              indented two
            """;
        // Closing delimiter on the last text line: no trailing newline
        String b = """
            no newline""";
        // \s keeps a trailing space; backslash at end of line joins lines
        String c = """
            keep\s
            joined \
            here""";
        // Triple quotes inside need one escaped quote
        String d = """
            say \"""hi\"""
            """;
        String e = """
            Hello, %s! You are %d.""".formatted("Bob", 30);   // no interpolation: use formatted()
        show("a", a); show("b", b); show("c", c); show("d", d); show("e", e);
    }

    static void show(String name, String s) {
        // make whitespace visible: \n -> $
        System.out.println(name + ": [" + s.replace("\n", "$\n") + "]");
    }
}

import java.lang.reflect.*;
import java.util.*;

public class Main {
    static class Base { public void hello() {} private void baseSecret() {} }
    static class Child extends Base {
        public void work() {}
        private void secret() { throw new IllegalStateException("boom from secret"); }
    }

    static List<String> names(Method[] ms) {
        List<String> l = new ArrayList<>();
        for (Method m : ms) if (m.getDeclaringClass() != Object.class) l.add(m.getName());
        Collections.sort(l);
        return l;
    }

    public static void main(String[] args) throws Exception {
        // getMethods: public only, includes inherited; getDeclaredMethods: this class only, any access
        System.out.println("getMethods:         " + names(Child.class.getMethods()));
        System.out.println("getDeclaredMethods: " + names(Child.class.getDeclaredMethods()));

        Method secret = Child.class.getDeclaredMethod("secret");
        secret.setAccessible(true);                       // needed to call a private method
        try {
            secret.invoke(new Child());
        } catch (InvocationTargetException e) {
            // invoke wraps the real exception; the cause is what you want to log
            System.out.println("wrapper: " + e.getClass().getSimpleName());
            System.out.println("cause:   " + e.getCause());
        }
    }
}

import java.lang.reflect.*;

public class Main {
    interface Service {
        void outer();
        void inner();
    }

    static class RealService implements Service {
        public void outer() { System.out.println("  outer runs"); inner(); } // self-invocation: 'this', not proxy
        public void inner() { System.out.println("  inner runs"); }
    }

    public static void main(String[] args) {
        Service real = new RealService();
        // Proxy class generated at runtime; every call goes to the handler
        Service proxy = (Service) Proxy.newProxyInstance(
            Main.class.getClassLoader(), new Class<?>[] { Service.class },
            (p, method, a) -> {
                System.out.println("[advice] before " + method.getName());   // like opening a transaction
                Object r = method.invoke(real, a);
                System.out.println("[advice] after " + method.getName());
                return r;
            });
        System.out.println("call proxy.outer():");
        proxy.outer();   // advice for outer only: inner() was called on 'this', bypassing the proxy
        System.out.println("call proxy.inner():");
        proxy.inner();   // advice runs because the call goes through the proxy
        System.out.println("is proxy class: " + Proxy.isProxyClass(proxy.getClass()));
    }
}

import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class Main {
    @Retention(RetentionPolicy.SOURCE)  @interface SrcOnly {}
    @Retention(RetentionPolicy.CLASS)   @interface ClassOnly {}   // the default retention
    @Retention(RetentionPolicy.RUNTIME) @interface Runtime {}

    @Retention(RetentionPolicy.RUNTIME) @Repeatable(Tags.class) @interface Tag { String value(); }
    @Retention(RetentionPolicy.RUNTIME) @interface Tags { Tag[] value(); }

    @SrcOnly @ClassOnly @Runtime
    static class Target {}

    @Tag("a") @Tag("b")
    static class Repeated {}

    @Tag("only")
    static class Single {}

    public static void main(String[] args) {
        // Only RUNTIME annotations are visible through reflection
        System.out.println("visible on Target: " + Arrays.toString(Target.class.getAnnotations()));
        // A repeated annotation is wrapped in its container
        System.out.println("getAnnotation(Tag) on Repeated: " + Repeated.class.getAnnotation(Tag.class));
        System.out.println("getAnnotationsByType: " + Repeated.class.getAnnotationsByType(Tag.class).length);
        System.out.println("single getAnnotation not null: " + (Single.class.getAnnotation(Tag.class) != null));
        // Annotation instances are JDK proxies
        System.out.println("is proxy: " + Proxy.isProxyClass(Single.class.getAnnotation(Tag.class).getClass()));
    }
}

import java.lang.reflect.*;

public class Main {
    public static void main(String[] args) throws Exception {
        // Old libraries did this to reach JDK internals; JDK 16+ blocks it by default
        Field f = String.class.getDeclaredField("value");
        try {
            f.setAccessible(true);
            System.out.println("opened (JVM started with --add-opens)");
        } catch (InaccessibleObjectException e) {
            System.out.println("blocked: " + e.getClass().getSimpleName());
        }
        // Supported alternative: use public API, or privateLookupIn on YOUR OWN classes
        System.out.println("chars via public API: " + "abc".toCharArray().length);
        Field own = Own.class.getDeclaredField("secret");
        own.setAccessible(true);                                  // fine: same unnamed module
        System.out.println("own private field: " + own.get(new Own()));
    }
    static class Own { private String secret = "mine"; }
}

public class Main {
    static int work(int n) {                    // small pure function to measure
        int s = 0;
        for (int i = 0; i < n; i++) s += i % 7;
        return s;
    }

    static volatile int sink;                   // consuming the result defeats dead-code elimination

    public static void main(String[] args) {
        int input = 1000;                       // real benchmarks keep inputs in state, not constants
        // Warm-up: let the JIT compile before measuring
        for (int i = 0; i < 20000; i++) sink = work(input);
        // Several measured runs: look at the spread, not one number
        long[] runs = new long[5];
        for (int r = 0; r < runs.length; r++) {
            long t0 = System.nanoTime();
            for (int i = 0; i < 20000; i++) sink = work(input);
            runs[r] = System.nanoTime() - t0;
        }
        long min = Long.MAX_VALUE, max = 0;
        for (long x : runs) { min = Math.min(min, x); max = Math.max(max, x); }
        System.out.println("result consumed: " + sink);
        System.out.println("runs measured: " + runs.length);
        System.out.println("spread exists (max >= min): " + (max >= min));
        System.out.println("Use JMH (@Warmup, @Fork, Blackhole) for trustworthy numbers.");
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Integer a = 127, b = 127;
        Integer c = 128, d = 128;
        System.out.println("127 == 127: " + (a == b));            // cached instances, same object
        System.out.println("128 == 128: " + (c == d));            // two different objects
        System.out.println("128 equals 128: " + c.equals(d));     // correct comparison
        System.out.println("Objects.equals: " + Objects.equals(c, d));
        int prim = 128;
        System.out.println("Integer == int: " + (c == prim));     // unboxes, compares values
        Map<Long, String> m = new HashMap<>();
        m.put(1L, "one");
        int key = 1;
        System.out.println("get(int) boxes to Integer: " + m.get(key));   // null, Integer never equals Long
        System.out.println("get(long): " + m.get((long) key));
    }
}

public class Main {
    static class Parent {
        static { System.out.println("1 Parent static block"); }
        int pf = init("3 Parent field initializer");
        { System.out.println("4 Parent instance block"); }
        Parent() {
            System.out.println("5 Parent constructor");
            show();                                   // overridable call from constructor: the pitfall
        }
        void show() {}
        static int init(String s) { System.out.println(s); return 1; }
    }

    static class Child extends Parent {
        static { System.out.println("2 Child static block"); }
        String name = "set";
        int cf = init("6 Child field initializer");
        Child() { super(); System.out.println("7 Child constructor body"); }
        @Override void show() { System.out.println("   show() sees name=" + name); } // still null here
    }

    public static void main(String[] args) {
        System.out.println("-- before new Child()");
        new Child();
        System.out.println("-- second instance: no static blocks again");
        new Child();
    }
}

import java.util.*;

public class Main {
    // Style A: sealed data + operations as switches (easy to add operations)
    sealed interface Expr permits Num, Add, Mul {}
    record Num(int v) implements Expr {}
    record Add(Expr l, Expr r) implements Expr {}
    record Mul(Expr l, Expr r) implements Expr {}

    static int eval(Expr e) {
        return switch (e) {
            case Num n -> n.v();
            case Add a -> eval(a.l()) + eval(a.r());
            case Mul m -> eval(m.l()) * eval(m.r());
        };
    }
    // A new operation is just one new method; no existing class is touched
    static String show(Expr e) {
        return switch (e) {
            case Num n -> String.valueOf(n.v());
            case Add a -> "(" + show(a.l()) + " + " + show(a.r()) + ")";
            case Mul m -> show(m.l()) + " * " + show(m.r());
        };
    }

    // Style B: polymorphism (easy to add new types, e.g. user-supplied strategies)
    interface Discount { double apply(double price); }

    public static void main(String[] args) {
        Expr e = new Add(new Num(2), new Mul(new Num(3), new Num(4)));
        System.out.println(show(e) + " = " + eval(e));
        List<Discount> ds = List.of(p -> p * 0.9, p -> p - 5);   // open set: anyone can add one
        double price = 100;
        for (Discount d : ds) price = d.apply(price);
        System.out.println("price after discounts: " + price);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(List.of(1, 2, 3));
        // Uniform first/last access (before Java 21: list.get(list.size() - 1))
        System.out.println("first=" + list.getFirst() + " last=" + list.getLast());
        list.addFirst(0);
        list.addLast(4);
        System.out.println("after add: " + list);

        List<Integer> rev = list.reversed();           // a live VIEW, not a copy
        list.add(5);
        System.out.println("reversed view sees new item: " + rev);

        LinkedHashMap<String, Integer> m = new LinkedHashMap<>();
        m.put("a", 1); m.put("b", 2);
        m.putFirst("z", 0);                            // SequencedMap method
        System.out.println("map: " + m + " first=" + m.firstEntry());

        try {
            List.of(1, 2).addFirst(0);                 // unmodifiable list
        } catch (UnsupportedOperationException e) {
            System.out.println("List.of addFirst -> UnsupportedOperationException");
        }
    }
}
